internal sealed class QS
{
    public float Total;
    public bool Used;
    public int RV, SV, CV, IV, LV;

    public float Rot(float vx, float vy, float vz, float angleDeg)
    {
        var axis = new Vector3(vx, vy, vz);
        float ang = RV == 3 ? angleDeg : MathHelper.ToRadians(angleDeg);
        var a2 = axis;
        if (RV == 1 && axis != Vector3.Zero)
            a2 = Vector3.Normalize(axis);
        var q = Quaternion.CreateFromAxisAngle(a2, ang);
        var m = Matrix.CreateFromQuaternion(q);
        var r = Vector3.Transform(Vector3.UnitX, m);
        float s = RV == 2 ? Vector3.Dot(r, Vector3.UnitX) : Vector3.Dot(r, a2);
        Total += s;
        Used = true;
        return s;
    }

    public float Slerp(float t, float fromAngle, float toAngle)
    {
        Quaternion a, b;
        if (SV == 1)
        {
            a = Quaternion.CreateFromYawPitchRoll(fromAngle, fromAngle, fromAngle);
            b = Quaternion.CreateFromYawPitchRoll(toAngle, toAngle, toAngle);
        }
        else if (SV == 2)
        {
            a = Quaternion.CreateFromYawPitchRoll(fromAngle, 0f, 0f);
            b = Quaternion.CreateFromYawPitchRoll(0f, toAngle, 0f);
        }
        else
        {
            a = Quaternion.CreateFromYawPitchRoll(fromAngle, 0f, 0f);
            b = Quaternion.CreateFromYawPitchRoll(toAngle, 0f, 0f);
        }
        var q = Quaternion.Slerp(a, b, t);
        float s = q.Length();
        if (SV == 3)
            s = q.Length() * t;
        Total += s;
        Used = true;
        return s;
    }

    public float Concat(float yaw, float pitch, float roll)
    {
        Quaternion qy, qp, qr;
        if (CV == 1)
        {
            qy = Quaternion.CreateFromAxisAngle(Vector3.UnitX, yaw);
            qp = Quaternion.CreateFromAxisAngle(Vector3.UnitY, pitch);
            qr = Quaternion.CreateFromAxisAngle(Vector3.UnitZ, roll);
        }
        else
        {
            qy = Quaternion.CreateFromAxisAngle(Vector3.UnitY, yaw);
            qp = Quaternion.CreateFromAxisAngle(Vector3.UnitX, pitch);
            qr = Quaternion.CreateFromAxisAngle(Vector3.UnitZ, roll);
        }
        var q = Quaternion.Concatenate(Quaternion.Concatenate(qy, qp), qr);
        q = Quaternion.Normalize(q);
        float s = CV == 2 ? Quaternion.Dot(q, q) : Quaternion.Dot(q, Quaternion.Identity);
        Total += s;
        Used = true;
        return s;
    }

    public float Inv(float vx, float vy, float vz)
    {
        var v = new Vector3(vx, vy, vz);
        var axis = v;
        if (IV == 1 && v != Vector3.Zero)
            axis = Vector3.Normalize(v);
        float ang = IV == 2 ? MathHelper.PiOver2 : MathHelper.PiOver4;
        var q = Quaternion.CreateFromAxisAngle(axis, ang);
        var inv = Quaternion.Inverse(q);
        var p = Quaternion.Multiply(q, inv);
        float s = IV == 3 ? p.W + p.X + p.Y + p.Z : p.W;
        Total += s;
        Used = true;
        return s;
    }

    public float Lerp(float t, float angle1, float angle2)
    {
        Quaternion q1, q2;
        if (LV == 1)
        {
            q1 = new Quaternion(angle1, 0f, 0f, 1f);
