        };
        (float, float, float)[] lerpArgs = slerpArgs;

        int rvN = 1, svN = 1, cvN = 1, ivN = 1, lvN = 1;
        if (args.Length > 0 && args[0] == "wide")
        {
            rvN = 4; svN = 4; cvN = 3; ivN = 4; lvN = 4;
        }

        long count = 0;
        var sb = new StringBuilder();
        foreach (var so in stateOrders)
        foreach (var qp in qPlaces)
        foreach (var dm in dampMods)
        foreach (var f in factors)
        foreach (var qm in qMods)
        foreach (var h in hVars)
        foreach (var ra in rotAngles)
        for (int sa = 0; sa < slerpArgs.Length; sa++)
        for (int ca = 0; ca < concatArgs.Length; ca++)
        for (int la = 0; la < lerpArgs.Length; la++)
        for (int rv = 0; rv < rvN; rv++)
        for (int sv = 0; sv < svN; sv++)
        for (int cv = 0; cv < cvN; cv++)
        for (int iv = 0; iv < ivN; iv++)
