    static string RunSim(string so, char qp, int dm, float factor, int qm, int h, float rotAngle,
        (float, float, float) sargs, (float, float, float) cargs, (float, float, float) largs, QS qs)
    {
        var ents = new List<Ent>();
        int score = 0;

        for (int tick = 0; tick < Ticks; tick++)
        {
            foreach (var s in Spawns)
            {
                if (s.Tick != tick)
                    continue;
                ents.Add(new Ent { Id = s.Id, P = new Vector3(s.X, s.Y, s.Z), V = Vector3.Zero });
            }
            foreach (var imp in Impulses)
            {
                if (imp.Tick != tick)
                    continue;
                var e = ents.FirstOrDefault(x => x.Id == imp.Entity);
                if (e == null)
                    continue;
                e.V = Vector3.Add(e.V, new Vector3(imp.Dx, imp.Dy, imp.Dz));
            }

            if (so == "SITD")
            {
                Integrate(ents, ref score);
                if (qp == 'T')
                    Quat(ents, tick, qm, h, rotAngle, sargs, cargs, largs, qs, ref score);
                Dampen(ents, tick, dm, factor);
            }
            else
            {
                Dampen(ents, tick, dm, factor);
                if (qp == 'T')
                    Quat(ents, tick, qm, h, rotAngle, sargs, cargs, largs, qs, ref score);
                Integrate(ents, ref score);
            }

            if (qp == 'D')
                Quat(ents, tick, qm, h, rotAngle, sargs, cargs, largs, qs, ref score);
            if (qp == 'E')
                Quat(ents, tick, qm, h, rotAngle, sargs, cargs, largs, qs, ref score);
        }

        var list = new List<Dictionary<string, object>>();
        foreach (var e in ents.OrderBy(x => x.Id))
        {
            list.Add(new Dictionary<string, object>
            {
                ["id"] = e.Id,
                ["px"] = e.P.X,
                ["py"] = e.P.Y,
                ["pz"] = e.P.Z,
                ["vx"] = e.V.X,
                ["vy"] = e.V.Y,
                ["vz"] = e.V.Z,
            });
        }
        var final = new Dictionary<string, object>
        {
            ["seed"] = 424242,
            ["scenario"] = "transform_arena_hard",
            ["ticks"] = Ticks,
            ["score"] = score,
            ["quaternion_score"] = qs.Total,
            ["entities"] = list,
        };
        return JsonSerializer.Serialize(final, Opts);
    }

    static void Integrate(List<Ent> ents, ref int score)
    {
        foreach (var e in ents)
        {
            if (e.V == Vector3.Zero)
                continue;
            e.P += e.V;
            var m = Matrix.CreateRotationY(0.25f);
            var v = Vector3.Transform(Vector3.UnitX, m);
            score += (int)(Vector3.Dot(v, e.V) * 100f);
        }
    }

    static void Dampen(List<Ent> ents, int tick, int dm, float factor)
    {
        if (dm > 1 && tick % dm != 0)
            return;
        foreach (var e in ents)
        {
            if (e.V == Vector3.Zero)
                continue;
            e.V = Vector3.Multiply(e.V, factor);
        }
    }

    static void Quat(List<Ent> ents, int tick, int qm, int h, float rotAngle,
        (float, float, float) sargs, (float, float, float) cargs, (float, float, float) largs, QS qs, ref int score)
    {
        if (qm > 1 && tick % qm != 0)
            return;
        foreach (var e in ents)
        {
            float s = 0f;
            s += qs.Rot(e.V.X, e.V.Y, e.V.Z, rotAngle);
            s += qs.Slerp(sargs.Item1, sargs.Item2, sargs.Item3);
            s += qs.Concat(cargs.Item1, cargs.Item2, cargs.Item3);
            s += qs.Inv(e.V.X, e.V.Y, e.V.Z);
            s += qs.Lerp(largs.Item1, largs.Item2, largs.Item3);
            if (h == 1)
                score += (int)(s * 100f);
            else if (h == 2)
                score += (int)(s * 10f);
            else if (h == 3)
                score += (int)s;
        }
    }

    static void LoadReplay(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        foreach (var s in doc.RootElement.GetProperty("spawnPlan").EnumerateArray())
        {
            Spawns.Add(new SpawnE
            {
                Tick = s.GetProperty("tick").GetInt32(),
                Id = s.GetProperty("id").GetInt32(),
                X = s.GetProperty("x").GetSingle(),
                Y = s.GetProperty("y").GetSingle(),
                Z = s.GetProperty("z").GetSingle(),
            });
        }
        foreach (var s in doc.RootElement.GetProperty("impulses").EnumerateArray())
        {
            Impulses.Add(new ImpE
            {
                Tick = s.GetProperty("tick").GetInt32(),
                Entity = s.GetProperty("entity").GetInt32(),
                Dx = s.GetProperty("dx").GetSingle(),
                Dy = s.GetProperty("dy").GetSingle(),
                Dz = s.GetProperty("dz").GetSingle(),
            });
        }
    }
