139	                ents.Add(new Ent { Id = s.id, P = new Vector3(s.x, s.y, s.z), V = Vector3.Zero });
140	            foreach (var imp in Impulses.Where(x => x.tick == tick))
141	            {
142	                var e = ents.FirstOrDefault(x => x.Id == imp.ent);
143	                if (e == null)
144	                    continue;
145	                e.V = Vector3.Add(e.V, new Vector3(imp.dx, imp.dy, imp.dz));
146	            }
147	            if (integrateFirst)
148	            {
149	                score += Integrate(ents);
150	                Dampen(ents, tick, cond, factor, zeroMode);
151	            }
152	            else
153	            {
154	                Dampen(ents, tick, cond, factor, zeroMode);
155	                score += Integrate(ents);
156	            }
157	        }
158	        return (score, ents);
159	    }
