161	    static int Integrate(List<Ent> ents)
162	    {
163	        int score = 0;
164	        foreach (var e in ents)
165	        {
166	            if (e.V == Vector3.Zero)
167	                continue;
168	            e.P += e.V;
169	            var m = Matrix.CreateRotationY(0.25f);
170	            var v = Vector3.Transform(Vector3.UnitX, m);
171	            score += (int)(Vector3.Dot(v, e.V) * 100f);
172	        }
173	        return score;
174	    }
