176	    static void Dampen(List<Ent> ents, int tick, Func<int, bool> cond, float factor, int zeroMode)
177	    {
178	        if (!cond(tick))
179	            return;
180	        foreach (var e in ents)
181	        {
182	            if (e.V == Vector3.Zero)
183	                continue;
184	            e.V = Vector3.Multiply(e.V, factor);
185	            if (zeroMode == 1 && e.V.Length() < 0.01f)
186	                e.V = Vector3.Zero;
187	            if (zeroMode == 2 && e.V.LengthSquared() < 0.0001f)
188	                e.V = Vector3.Zero;
189	        }
190	    }
