192	    static (byte[] prefix, byte[] suffix, string canonNoQ) Build(int score, List<Ent> ents)
193	    {
194	        var sb = new StringBuilder();
195	        sb.Append("{\"entities\":[");
196	        bool first = true;
197	        foreach (var e in ents.OrderBy(x => x.Id))
198	        {
199	            if (!first)
200	                sb.Append(',');
201	            first = false;
202	            sb.Append("{\"id\":").Append(e.Id.ToString(CultureInfo.InvariantCulture));
203	            sb.Append(",\"px\":").Append(Py.Num(e.P.X));
204	            sb.Append(",\"py\":").Append(Py.Num(e.P.Y));
205	            sb.Append(",\"pz\":").Append(Py.Num(e.P.Z));
206	            sb.Append(",\"vx\":").Append(Py.Num(e.V.X));
207	            sb.Append(",\"vy\":").Append(Py.Num(e.V.Y));
208	            sb.Append(",\"vz\":").Append(Py.Num(e.V.Z));
209	            sb.Append('}');
210	        }
211	        sb.Append("],\"quaternion_score\":");
212	        string pre = sb.ToString();
213	        string suf = ",\"scenario\":\"" + Scenario + "\",\"score\":" + score.ToString(CultureInfo.InvariantCulture)
214	            + ",\"seed\":" + Seed.ToString(CultureInfo.InvariantCulture) + ",\"ticks\":" + Ticks.ToString(CultureInfo.InvariantCulture) + "}";
215	        return (Encoding.UTF8.GetBytes(pre), Encoding.UTF8.GetBytes(suf), pre + "<Q>" + suf);
216	    }
