218	    static string Hash(byte[] pre, byte[] suf, string q)
219	    {
220	        var buf = new byte[pre.Length + suf.Length + 64];
221	        Buffer.BlockCopy(pre, 0, buf, 0, pre.Length);
222	        int n = pre.Length;
223	        for (int i = 0; i < q.Length; i++)
224	            buf[n++] = (byte)q[i];
225	        Buffer.BlockCopy(suf, 0, buf, n, suf.Length);
226	        n += suf.Length;
227	        var h = SHA256.HashData(buf.AsSpan(0, n));
228	        return Convert.ToHexString(h).ToLowerInvariant();
229	    }
